mapper.sql:

WHERE 1=1 
AND IC.폐기일자 <= CONVERT(VARCHAR,GETDATE(),112)
AND (UPC.거래정지일자 = '00000000' OR UPC.거래정지일자 >=CONVERT(VARCHAR,GETDATE(),112) )
AND WO.접수확인 = 'N'
AND WO.진행유무 = 'Y'
AND WO.접수삭제 = 'N'
AND WO.거래처코드 = #{bcncCode}




		 AND WO.납기일자 >= #{searchDtFrom} 


		 AND WO.납기일자 <= #{searchDtTo} 




		 AND WO.접수일자 >= #{searchDtFrom} 


		 AND WO.접수일자 <= #{searchDtTo} 




 AND IC.품목명 LIKE UPPER('%'+ #{searchItemNm} +'%') 


 AND WO.착지업체 IN (#{alocEntrps})

update.foreach:
UPDATE 웹주문접수 SET
	거래처재고중량 = DBO.웹_재고중량_함수(#{item.wDedt}, #{item.wIcCode}, 'C', #{item.wRceptde}, #{item.wSn})
	, 주문비고 = #{item.wNote}
	, 수정자 = #{bcncCode}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 접수일자 = #{item.wRceptde}
	AND 일련번호 = #{item.wSn}
